from typing import List

def prime_fib(n: int) -> int:
    def is_prime(x: int) -> bool:
        if x <= 1:
            return False
        if x == 2:
            return True
        if x % 2 == 0:
            return False
        for i in range(3, int(x ** 0.5) + 1, 2):
            if x % i == 0:
                return False
        return True

    count = 0
    a, b = 0, 1
    while True:
        current = a
        if is_prime(current):
            count += 1
            if count == n:
                return current
        a, b = b, a + b

