from typing import List

def circular_shift(x: int, shift: int) -> str:
    s = str(x)
    n = len(s)
    if shift > n:
        return s[::-1]
    effective_shift = shift % n
    if effective_shift == 0:
        return s
    return s[-effective_shift:] + s[:-effective_shift]

