from typing import List

def pluck(arr: List[int]) -> List[int]:
    current_min_value = None
    current_min_index = None
    for index, num in enumerate(arr):
        if num % 2 == 0:
            if current_min_value is None:
                current_min_value = num
                current_min_index = index
            else:
                if num < current_min_value:
                    current_min_value = num
                    current_min_index = index
                elif num == current_min_value:
                    if index < current_min_index:
                        current_min_index = index
    return [current_min_value, current_min_index] if current_min_value is not None else []

