from typing import List

def is_multiply_prime(a: int) -> bool:
    def is_prime(n: int) -> bool:
        if n <= 1:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        for i in range(3, int(n ** 0.5) + 1, 2):
            if n % i == 0:
                return False
        return True

    primes = [n for n in range(2, a + 1) if is_prime(n)]
    for p in primes:
        if a % p != 0:
            continue
        a1 = a // p
        for q in primes:
            if a1 % q != 0:
                continue
            a2 = a1 // q
            if is_prime(a2):
                return True
    return False

