def iscube(a):
    if a == 0:
        return True
    x = abs(a)
    low = 0
    high = x
    while low <= high:
        mid = (low + high) // 2
        mid_cubed = mid ** 3
        if mid_cubed == x:
            return True
        elif mid_cubed < x:
            low = mid + 1
        else:
            high = mid - 1
    return False

