import math

def closest_integer(value: str) -> int:
    x = float(value)
    lower = math.floor(x)
    upper = lower + 1
    d_lower = abs(x - lower)
    d_upper = abs(x - upper)
    if d_lower < d_upper:
        return int(lower)
    elif d_upper < d_lower:
        return int(upper)
    else:
        return int(lower) if abs(lower) > abs(upper) else int(upper)

