from typing import List

def f(n: int) -> List[int]:
    result = []
    prev_even_fact = 1  # Represents 0! = 1 for initial calculation
    for i in range(1, n + 1):
        if i % 2 == 0:
            current_fact = prev_even_fact * (i - 1) * i
            prev_even_fact = current_fact
            result.append(current_fact)
        else:
            sum_val = i * (i + 1) // 2
            result.append(sum_val)
    return result

