def histogram(test: str) -> Dict[str, int]:
    letters = test.split()
    freq = {}
    for letter in letters:
        freq[letter] = freq.get(letter, 0) + 1
    if not freq:
        return {}
    max_count = max(freq.values())
    return {k: v for k, v in freq.items() if v == max_count}

