    vowels = {'a', 'e', 'i', 'o', 'u', 'A', 'E', 'I', 'O', 'U'}
    n = len(word)
    for i in range(n-1, -1, -1):
        char = word[i]
        if char in vowels:
            if i == 0 or i == n - 1:
                continue
            prev = word[i-1]
            next_char = word[i+1]
            if prev not in vowels and next_char not in vowels:
                return char
    return ""

