from typing import List

def match_parens(lst: List[str]) -> str:
    s1, s2 = lst

    def compute_props(s: str) -> tuple[int, int]:
        balance = 0
        min_balance = 0
        for c in s:
            if c == '(':
                balance += 1
            else:
                balance -= 1
            min_balance = min(min_balance, balance)
        return balance, min_balance

    total1, min1 = compute_props(s1)
    total2, min2 = compute_props(s2)

    if total1 + total2 != 0:
        return 'No'

    if (min1 >= 0 and (min2 + total1) >= 0) or (min2 >= 0 and (min1 + total2) >= 0):
        return 'Yes'
    else:
