from typing import List

def get_odd_collatz(n: int) -> List[int]:
    sequence = []
    current = n
    while current != 1:
        sequence.append(current)
        if current % 2 == 0:
            current = current // 2
        else:
            current = 3 * current + 1
    sequence.append(1)
    odds = [num for num in sequence if num % 2 == 1]
    return sorted(odds)

