from typing import List

def valid_date(date: str) -> bool:
    if len(date) != 10:
        return False
    if date[2] != '-' or date[4] != '-':
        return False
    parts = date.split('-')
    if len(parts) != 3:
        return False
    if not (parts[0].isdigit() and parts[1].isdigit() and parts[2].isdigit()):
        return False
    if len(parts[0]) != 2 or len(parts[1]) != 2 or len(parts[2]) != 4:
        return False
    try:
        mm = int(parts[0])
        dd = int(parts[1])
        yyyy = int(parts[2])
    except ValueError:
        return False
    if mm < 1 or mm > 12:
        return False
    if dd < 1:
        return False
    if mm in [1, 3, 5, 7, 8, 10, 12]:
        max_day = 31
    elif mm in [4, 6, 9, 11]:
        max_day = 30
    else:
        max_day = 29
    if dd > max_day:
        return False
    return True

