from typing import List, Optional

def prod_signs(arr: List[int]) -> Optional[int]:
    if not arr:
        return None
    sum_abs = sum(abs(num) for num in arr)
    product_sign = 1
    for num in arr:
        if num == 0:
            product_sign = 0
            break
        else:
            product_sign *= 1 if num > 0 else -1
    return sum_abs * product_sign

