import re

def fix_spaces(text):
    parts = re.findall(r'( +)|([^ ]+)', text)
    result = []
    for space, non_space in parts:
        if space:
            if len(space) >= 3:
                result.append('-')
            else:
                result.append('_' * len(space))
        else:
            result.append(non_space)
    return ''.join(result)

