from typing import List

def double_the_difference(lst: List[float]) -> int:
    total = 0
    for num in lst:
        if num < 0:
            continue
        if isinstance(num, int):
            if num % 2 != 0:
                total += num ** 2
        elif isinstance(num, float):
            if num.is_integer():
                int_num = int(num)
                if int_num % 2 != 0:
                    total += int_num ** 2
    return total

