from typing import List

def find_max(words: List[str]) -> str:
    best_word = ""
    max_count = -1
    for word in words:
        current_count = len(set(word))
        if current_count > max_count:
            max_count = current_count
            best_word = word
        elif current_count == max_count:
            if word < best_word:
                best_word = word
    return best_word

